#!/usr/bin/env bash
# capacitor-cordova-android-plugins is generated by `npx cap sync` and gitignored.
# Unit tests only need the empty library plus cordova.variables.gradle, not a web build.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
dest="$root/android/capacitor-cordova-android-plugins"
archive="$root/node_modules/@capacitor/cli/assets/capacitor-cordova-android-plugins.tar.gz"
mkdir -p "$dest"
tar -xzf "$archive" -C "$dest"
if ! grep -q 'cordova.variables.gradle' "$dest/build.gradle"; then
  sed -i 's|// PLUGIN GRADLE EXTENSIONS START|// PLUGIN GRADLE EXTENSIONS START\napply from: "cordova.variables.gradle"|' "$dest/build.gradle"
fi
cat > "$dest/cordova.variables.gradle" << 'EOF'
// DO NOT EDIT THIS FILE! IT IS GENERATED EACH TIME "capacitor update" IS RUN
ext {
  cdvMinSdkVersion = project.hasProperty('minSdkVersion') ? rootProject.ext.minSdkVersion : 26
  cdvPluginPostBuildExtras = []
  cordovaConfig = [:]
}
EOF
